import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

// Asli colorful Google "G" logo — koi asset file, folder ya package ki
// zaroorat NAHI. Image seedha code ke andar (base64) embedded hai.
// Use: const GoogleLogo(size: 22)

final Uint8List _googleLogoBytes = base64Decode(_kGoogleLogoBase64);

class GoogleLogo extends StatelessWidget {
  final double size;
  const GoogleLogo({super.key, this.size = 22});

  @override
  Widget build(BuildContext context) {
    return Image.memory(
      _googleLogoBytes,
      width: size,
      height: size,
      gaplessPlayback: true,
    );
  }
}

const String _kGoogleLogoBase64 =
    '';
